const STATUS_OPTIONS=['Recebida','Em avaliação','Aguardando aprovação','Em reparo','Pronta para retirada','Concluída','Cancelada'];
let settings={};let requests=[];let reviews=[];let photoComments=[];let cashOrders=[];let monthlyReport=null;let titheReceiptUrl=null;
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function setPath(object,path,value){const keys=path.split('.');let node=object;while(keys.length>1)node=node[keys.shift()];node[keys[0]]=value;}
function getPath(object,path){return path.split('.').reduce((value,key)=>value?.[key],object);}
function renderRepeater(path,items){const box=document.querySelector(`[data-repeat="${path}"]`);if(!box)return;box.innerHTML=items.map((item,index)=>{let fields;if(path==='socialLinks')fields=`<label>Rede social ${index+1}<input data-item="name" maxlength="60" required value="${esc(item.name)}" placeholder="Instagram, Facebook…"></label><label>Link público<input data-item="url" type="url" maxlength="400" required value="${esc(item.url)}" placeholder="https://"></label>`;else if(path==='reviews')fields=`<label>Cliente ${index+1}<input data-item="name" maxlength="100" required value="${esc(item.name)}"></label><label>Nota<select data-item="rating">${[5,4,3,2,1].map(rating=>`<option value="${rating}" ${Number(item.rating||5)===rating?'selected':''}>${rating} estrelas</option>`).join('')}</select></label><label>Avaliação<textarea data-item="text" rows="2" maxlength="1200" required>${esc(item.text)}</textarea></label>`;else fields=`<label>${esc(box.dataset.label)} ${index+1}<input data-item="title" maxlength="120" required value="${esc(item.title)}"></label><label>Descrição<textarea data-item="description" rows="2" maxlength="1200" required>${esc(item.description)}</textarea></label>`;return `<div class="editor-row">${fields}<button type="button" class="remove-row" aria-label="Remover ${esc(box.dataset.label)} ${index+1}">Remover</button></div>`;}).join('');}
function renderGallery(items){const box=$('#photo-list');box.innerHTML=items.length?items.map((photo,index)=>`<article class="photo-item" data-photo-url="${esc(photo.url)}"><img src="${esc(photo.url)}" alt="${esc(photo.caption||'Foto de serviço da RS TECH')}"><label>Legenda ${index+1}<input data-photo-caption maxlength="160" value="${esc(photo.caption||'')}"></label><label>Link do vídeo do reparo (opcional)<input data-photo-video type="url" maxlength="500" value="${esc(photo.videoUrl||'')}" placeholder="https://youtube.com/…"></label><button type="button" class="remove-row remove-photo">Apagar publicação</button></article>`).join(''):'<p class="empty-note">Nenhuma foto adicionada ainda.</p>';}
function loadEditor(data){settings=data;document.querySelectorAll('[data-bind]').forEach(input=>input.value=getPath(settings,input.dataset.bind)||'');for(const box of document.querySelectorAll('[data-repeat]'))renderRepeater(box.dataset.repeat,getPath(settings,box.dataset.repeat)||[]);renderGallery(settings.gallery||[]);}
function gatherSettings(){const result=JSON.parse(JSON.stringify(settings));document.querySelectorAll('[data-bind]').forEach(input=>setPath(result,input.dataset.bind,input.value.trim()));for(const box of document.querySelectorAll('[data-repeat]')){let entries;if(box.dataset.repeat==='socialLinks')entries=[...box.querySelectorAll('.editor-row')].map(row=>({name:row.querySelector('[data-item="name"]').value.trim(),url:row.querySelector('[data-item="url"]').value.trim()}));else if(box.dataset.repeat==='reviews')entries=[...box.querySelectorAll('.editor-row')].map(row=>({name:row.querySelector('[data-item="name"]').value.trim(),rating:Number(row.querySelector('[data-item="rating"]').value),text:row.querySelector('[data-item="text"]').value.trim()}));else entries=[...box.querySelectorAll('.editor-row')].map(row=>({title:row.querySelector('[data-item="title"]').value.trim(),description:row.querySelector('[data-item="description"]').value.trim()}));setPath(result,box.dataset.repeat,entries);}result.gallery=[...document.querySelectorAll('.photo-item')].map(item=>({url:item.dataset.photoUrl,caption:item.querySelector('[data-photo-caption]').value.trim(),videoUrl:item.querySelector('[data-photo-video]').value.trim()}));return result;}
function requestCard(item){const select=STATUS_OPTIONS.map(option=>`<option ${item.status===option?'selected':''}>${option}</option>`).join('');const updates=item.progressUpdates||[];return `<article class="request-card" data-request="${esc(item.id)}"><h3>Solicitação · ${esc(item.device)}</h3><div class="request-meta"><span>Criada em ${esc(new Date(item.createdAt).toLocaleString('pt-BR'))}</span><span>Cliente: ${esc(item.customerId)}</span></div><div class="request-edit-grid"><label>Nome do cliente<input name="name" maxlength="100" value="${esc(item.name)}"></label><label>E-mail<input name="email" type="email" maxlength="254" value="${esc(item.email)}"></label><label>WhatsApp<input name="phone" maxlength="80" value="${esc(item.phone)}"></label><label>Aparelho<input name="device" maxlength="120" value="${esc(item.device)}"></label><label class="wide">Descrição do problema<textarea name="problem" maxlength="3000">${esc(item.problem)}</textarea></label><label>Status do serviço<select name="status">${select}</select></label><label class="wide">Observação interna (visível somente para a proprietária)<textarea name="internalNote" maxlength="3000" placeholder="Anote informações para acompanhar o atendimento">${esc(item.internalNote||'')}</textarea></label></div><div class="request-actions"><span class="request-save-message" role="status"></span><button class="button button-primary save-request" type="button">Salvar pedido</button><button class="small-button delete-request" type="button">Apagar solicitação</button></div><section class="service-progress-editor"><h4>Atualizações visíveis ao cliente</h4>${updates.length?updates.map(update=>`<article class="service-update-card">${update.imageUrl?`<img src="${esc(update.imageUrl)}" alt="${esc(update.caption||'Foto do andamento do reparo')}">`:''}<p>${esc(update.caption||'Atualização do serviço')}</p>${update.videoUrl?`<a href="${esc(update.videoUrl)}" target="_blank" rel="noopener noreferrer">Abrir vídeo relacionado ↗</a>`:''}<small>${esc(new Date(update.createdAt).toLocaleString('pt-BR'))}</small>${(update.comments||[]).map(comment=>`<blockquote><b>${esc(comment.name)}:</b> ${esc(comment.text)}</blockquote>`).join('')}</article>`).join(''):'<p class="empty-note">Ainda não há atualizações publicadas.</p>'}<div class="service-progress-form"><label>Foto (opcional)<input type="file" name="progressPhoto" accept="image/jpeg,image/png,image/webp"></label><label>Legenda ou mensagem para o cliente<textarea name="progressCaption" maxlength="500" placeholder="Ex.: aparelho em diagnóstico, peça substituída…"></textarea></label><label>Link de vídeo (Instagram, YouTube ou outro · opcional)<input type="url" name="progressVideo" maxlength="500" placeholder="https://…"></label><span class="progress-feedback" role="status"></span><button type="button" class="small-button publish-progress">Publicar atualização</button></div></section></article>`;}
function renderRequests(){const list=$('#requests');$('#total-count').textContent=requests.length;$('#request-count').textContent=requests.length;$('#open-count').textContent=requests.filter(item=>!['Concluída','Cancelada'].includes(item.status)).length;list.innerHTML=requests.length?requests.map(requestCard).join(''):'<div class="empty-note request-empty-state"><strong>Nenhuma solicitação recebida ainda.</strong><p>O acompanhamento, as fotos, legendas, vídeos e comentários aparecem dentro do pedido correspondente, depois que um cliente enviar uma solicitação de serviço.</p><a href="/?visao=cliente#contato" class="small-button">Ver a área de solicitação do cliente ↗</a></div>';}
function renderReviews(){const list=$('#review-list');$('#review-count').textContent=reviews.filter(review=>review.status==='Pendente').length;list.innerHTML=reviews.length?reviews.map(review=>`<article class="request-card" data-review="${esc(review.id)}"><h3>Avaliação de ${esc(review.name)}</h3><div class="request-meta"><span>${esc(new Date(review.createdAt).toLocaleString('pt-BR'))}</span><span>${esc(review.status)}</span></div><div class="request-edit-grid"><label>Nome<input name="name" maxlength="100" value="${esc(review.name)}"></label><label>Nota<select name="rating">${[5,4,3,2,1].map(rating=>`<option value="${rating}" ${Number(review.rating)===rating?'selected':''}>${rating} estrelas</option>`).join('')}</select></label><label class="wide">Comentário<textarea name="text" maxlength="1200">${esc(review.text)}</textarea></label><label>Status<select name="status">${['Pendente','Publicada','Rejeitada'].map(status=>`<option ${review.status===status?'selected':''}>${status}</option>`).join('')}</select></label></div><div class="request-actions"><span class="request-save-message" role="status"></span><button class="button button-primary save-review" type="button">Salvar avaliação</button><button class="small-button delete-review" type="button">Apagar avaliação</button></div></article>`).join(''):'<div class="empty-note">Nenhuma avaliação recebida ainda.</div>';}
function renderPhotoComments(){const list=$('#photo-comment-list');$('#photo-comment-count').textContent=photoComments.length;list.innerHTML=photoComments.length?photoComments.map(comment=>`<article class="request-card" data-photo-comment-id="${esc(comment.id)}"><h3>Comentário de ${esc(comment.name)}</h3><div class="request-meta"><span>${esc(new Date(comment.createdAt).toLocaleString('pt-BR'))}</span><span>Publicado automaticamente</span></div>${comment.photo?`<a class="comment-photo-link" href="${esc(comment.photo.url)}" target="_blank" rel="noreferrer"><img src="${esc(comment.photo.url)}" alt="${esc(comment.photo.caption||'Foto relacionada ao comentário')}"><span>${esc(comment.photo.caption||'Ver foto publicada')}</span></a>`:'<p class="comment-photo-missing">A foto relacionada não está mais publicada.</p>'}<div class="request-edit-grid"><label class="wide">Nome<input name="name" maxlength="100" value="${esc(comment.name)}"></label><label class="wide">Comentário<textarea name="text" maxlength="1000">${esc(comment.text)}</textarea></label></div><div class="request-actions"><span class="request-save-message" role="status"></span><button class="button button-primary save-photo-comment" type="button">Salvar edição</button><button class="small-button delete-photo-comment" type="button">Apagar comentário</button></div></article>`).join(''):'<div class="empty-note">Nenhum comentário nas fotos ainda. Os novos comentários aparecem automaticamente no site.</div>';}
async function loadRequests(){const response=await fetch('/api/admin/requests');if(!response.ok)throw new Error('Não foi possível carregar as solicitações.');requests=(await response.json()).requests;renderRequests();}
async function loadReviews(){const response=await fetch('/api/admin/reviews');if(!response.ok)throw new Error('Não foi possível carregar as avaliações.');reviews=(await response.json()).reviews;renderReviews();}
async function loadPhotoComments(){const response=await fetch('/api/admin/photo-comments');if(!response.ok)throw new Error('Não foi possível carregar os comentários das fotos.');photoComments=(await response.json()).comments;renderPhotoComments();}
const currency=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(value)||0);
function openReceiptPdf({kind,reference,date,customerName,customerEmail,customerPhone,item,amount,paymentStatus,paymentMethod,detail}){const company=settings.company?.fullName||'RS TECH ASSISTÊNCIA TÉCNICA CELULAR';const phone=settings.contact?.phoneDisplay||'';const address=settings.contact?.address||'';const content=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Comprovante RS TECH - ${esc(reference)}</title><style>*{box-sizing:border-box}body{margin:0;padding:36px;background:#fff;color:#111;font:14px Arial,sans-serif}.receipt{max-width:760px;margin:auto;border:1px solid #d6dce5;padding:34px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;border-bottom:2px solid #111;padding-bottom:18px}.brand{font-size:20px;font-weight:700}.sub{margin-top:4px;color:#555;font-size:12px}.badge{border:1px solid #555;padding:7px 10px;font-size:10px;font-weight:700;letter-spacing:1px}.title{margin:26px 0 5px;font-size:22px}.muted{color:#555;font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:24px}.field{border-bottom:1px solid #ddd;padding:0 0 9px}.label{display:block;margin-bottom:4px;color:#555;font-size:10px;text-transform:uppercase;letter-spacing:.6px}.value{font-weight:600}.line{margin-top:22px;padding:16px;background:#f3f5f7}.total{display:flex;justify-content:space-between;margin-top:20px;padding-top:14px;border-top:2px solid #111;font-size:18px;font-weight:700}.note{margin-top:28px;padding-top:12px;border-top:1px solid #ddd;color:#555;font-size:11px;line-height:1.6}.footer{margin-top:30px;text-align:center;color:#777;font-size:10px}@media print{body{padding:0}.receipt{max-width:none;border:0;padding:18mm}.no-print{display:none}}</style></head><body><main class="receipt"><header class="top"><div><div class="brand">${esc(company)}</div>${phone?`<div class="sub">WhatsApp: ${esc(phone)}</div>`:''}${address?`<div class="sub">${esc(address)}</div>`:''}</div><div class="badge">COMPROVANTE NÃO FISCAL</div></header><h1 class="title">Comprovante de ${esc(kind)}</h1><div class="muted">Documento de controle e atendimento · ${esc(reference)}</div><section class="grid"><div class="field"><span class="label">Data</span><span class="value">${esc(date)}</span></div><div class="field"><span class="label">Cliente</span><span class="value">${esc(customerName||'Não informado')}</span></div>${customerEmail?`<div class="field"><span class="label">E-mail</span><span class="value">${esc(customerEmail)}</span></div>`:''}${customerPhone?`<div class="field"><span class="label">WhatsApp do cliente</span><span class="value">${esc(customerPhone)}</span></div>`:''}<div class="field"><span class="label">Pagamento</span><span class="value">${esc(paymentStatus||'Não informado')}</span></div><div class="field"><span class="label">Forma de pagamento</span><span class="value">${esc(paymentMethod||'Não informada')}</span></div></section><section class="line"><span class="label">${kind==='reparo'?'Aparelho / serviço':'Produto'}</span><span class="value">${esc(item)}</span>${detail?`<div class="sub">${esc(detail)}</div>`:''}</section><div class="total"><span>Valor registrado</span><span>${esc(currency(amount))}</span></div><p class="note">Este documento é um comprovante não fiscal. Ele não substitui nota fiscal eletrônica ou outro documento fiscal emitido pelo sistema autorizado.</p><div class="footer">RS TECH · Gerado em ${esc(new Date().toLocaleString('pt-BR'))}</div></main><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250));</script></body></html>`;const printable=window.open('','_blank','width=820,height=900');if(!printable){alert('Permita a abertura da janela para imprimir ou salvar o comprovante em PDF.');return;}printable.document.open();printable.document.write(content);printable.document.close();}
function profitValues(charged,cost){const hasCharged=charged!==null&&charged!==undefined&&charged!==''&&Number.isFinite(Number(charged));const hasCost=cost!==null&&cost!==undefined&&cost!==''&&Number.isFinite(Number(cost));if(!hasCharged||!hasCost)return {profit:null,margin:null};const profit=Number(charged)-Number(cost);return {profit,margin:Number(charged)>0?profit/Number(charged)*100:null};}
function percent(value){return value===null?'—':`${value.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})}%`;}
function updateCashFormPreview(){const form=$('#cash-order-form');const values=profitValues(form.elements.amountCharged.value,form.elements.partCost.value);$('#cash-order-profit-preview').textContent=values.profit===null?'—':currency(values.profit);$('#cash-order-margin-preview').textContent=percent(values.margin);}
function renderCashSummary(){const amountOrders=cashOrders.filter(order=>order.amountCharged!==null&&order.amountCharged!==undefined);const costOrders=cashOrders.filter(order=>order.partCost!==null&&order.partCost!==undefined);const profitOrders=cashOrders.filter(order=>order.amountCharged!==null&&order.amountCharged!==undefined&&order.partCost!==null&&order.partCost!==undefined);const charged=amountOrders.reduce((sum,order)=>sum+Number(order.amountCharged),0);const expenses=costOrders.reduce((sum,order)=>sum+Number(order.partCost),0);const received=amountOrders.filter(order=>order.paymentStatus==='Pago').reduce((sum,order)=>sum+Number(order.amountCharged),0);const pending=amountOrders.filter(order=>order.paymentStatus==='Pendente').reduce((sum,order)=>sum+Number(order.amountCharged),0);const profit=profitOrders.reduce((sum,order)=>sum+Number(order.amountCharged)-Number(order.partCost),0);const profitBase=profitOrders.reduce((sum,order)=>sum+Number(order.amountCharged),0);$('#cash-revenue-total').textContent=currency(charged);$('#cash-expenses-total').textContent=currency(expenses);$('#cash-profit-total').textContent=profitOrders.length?currency(profit):'—';$('#cash-profit-margin').textContent=percent(profitBase>0?profit/profitBase*100:null);$('#cash-received-total').textContent=currency(received);$('#cash-pending-total').textContent=currency(pending);$('#cash-order-count').textContent=`${cashOrders.length} ${cashOrders.length===1?'ordem':'ordens'}`;}
function updateCashCardPreview(card){const values=profitValues(card.querySelector('[name="amountCharged"]').value,card.querySelector('[name="partCost"]').value);card.querySelector('.cash-card-profit').textContent=values.profit===null?'—':currency(values.profit);card.querySelector('.cash-card-margin').textContent=percent(values.margin);}
function cashOrderCard(order){const values=profitValues(order.amountCharged,order.partCost);const status=order.paymentStatus||'Não informado';const paymentMethod=order.paymentMethod||'Não informada';const entryType=order.entryType==='Venda'?'Venda':'Reparo';const saleItemType=order.saleItemType||'';const statusClass=status==='Pago'?'paid':status==='Pendente'?'pending':'unknown';return `<article class="request-card cash-order-card" data-cash-order="${esc(order.id)}"><div class="cash-order-title"><div><span class="cash-source-tag ${entryType==='Venda'?'sale':''}">${entryType}</span><h3>${esc(order.model||'Lançamento sem descrição')}</h3></div><span class="cash-payment ${statusClass}">${esc(status)}</span></div><div class="request-meta"><span>Lançada em ${esc(new Date(order.createdAt).toLocaleString('pt-BR'))}</span></div><div class="request-edit-grid"><label>Classificação<select name="entryType">${['Reparo','Venda'].map(item=>`<option value="${item}" ${entryType===item?'selected':''}>${item}</option>`).join('')}</select></label><label data-sale-item-type ${entryType==='Venda'?'':'hidden'}>Tipo do item vendido<select name="saleItemType">${['','Aparelho','Acessório','Produto'].map(item=>`<option value="${item}" ${saleItemType===item?'selected':''}>${item||'Não informado'}</option>`).join('')}</select></label><label>Modelo ou item (opcional)<input name="model" maxlength="120" value="${esc(order.model||'')}"></label><label>Valor cobrado (R$) · opcional<input name="amountCharged" type="number" min="0.01" step="0.01" value="${order.amountCharged??''}"></label><label>Custo da peça/produto (R$) · opcional<input name="partCost" type="number" min="0" step="0.01" value="${order.partCost??''}"></label><label>Status do pagamento (opcional)<select name="paymentStatus"><option value="" ${!order.paymentStatus?'selected':''}>Não informado</option>${['Pendente','Pago'].map(item=>`<option value="${item}" ${order.paymentStatus===item?'selected':''}>${item}</option>`).join('')}</select></label><label>Forma de pagamento (opcional)<select name="paymentMethod"><option value="" ${!order.paymentMethod?'selected':''}>Não informada</option>${['PIX','Dinheiro','Cartão de débito','Cartão de crédito','Transferência bancária','Outro'].map(item=>`<option value="${item}" ${order.paymentMethod===item?'selected':''}>${item}</option>`).join('')}</select></label><label>Tempo de reparo · opcional<input name="repairTime" maxlength="100" value="${esc(order.repairTime||'')}"></label><label>Cliente · opcional<input name="customerName" maxlength="100" value="${esc(order.customerName||'')}" placeholder="Nome do cliente"></label><label>Status da ordem<select name="completionStatus">${['Em andamento','Concluído'].map(value=>`<option ${((order.completionStatus||'Em andamento')===value)?'selected':''}>${value}</option>`).join('')}</select></label></div><div class="cash-card-result"><span>Lucro: <b class="cash-card-profit">${values.profit===null?'—':currency(values.profit)}</b></span><span>Margem: <b class="cash-card-margin">${percent(values.margin)}</b></span><span>Forma de pagamento: <b>${esc(paymentMethod)}</b></span>${entryType==='Venda'?`<span>Tipo vendido: <b>${esc(saleItemType||'Não informado')}</b></span>`:''}<span>Tempo: <b>${esc(order.repairTime||'Não informado')}</b></span></div><div class="request-actions"><span class="request-save-message" role="status"></span>${order.completionStatus==='Concluído'?'<button class="small-button print-cash-receipt" type="button">Comprovante PDF</button>':''}<button class="button button-primary save-cash-order" type="button">Salvar edição</button><button class="small-button delete-cash-order" type="button">Excluir lançamento</button></div></article>`;}
function renderCashOrders(){renderCashSummary();$('#cash-orders').innerHTML=cashOrders.length?cashOrders.map(cashOrderCard).join(''):'<div class="empty-note">Nenhuma ordem de serviço lançada ainda.</div>';}
async function loadCashOrders(){const response=await fetch('/api/admin/cash-orders');if(!response.ok)throw new Error('Não foi possível carregar o caixa.');cashOrders=(await response.json()).orders;renderCashOrders();}
let products=[];
function productCard(product){return `<article class="product-card" data-product="${esc(product.id)}"><div class="product-card-heading"><div><span class="product-category">${esc(product.category)}</span><h4>${esc(product.name)}</h4></div><span class="product-stock ${product.soldOut?'sold-out':''}">${product.soldOut?'ESGOTADO':`${Number(product.stock)||0} em estoque`}</span></div>${product.imageUrl?`<img class="product-admin-image" src="${esc(product.imageUrl)}" alt="Foto de ${esc(product.name)}">`:''}<div class="product-edit-grid"><label>Nome<input name="name" maxlength="120" value="${esc(product.name)}"></label><label>Categoria<select name="category">${['Acessórios','Aparelhos','Peças','Outros'].map(category=>`<option value="${category}" ${product.category===category?'selected':''}>${category}</option>`).join('')}</select></label><label>Preço de venda (R$)<input name="price" type="number" min="0" step="0.01" value="${Number(product.price)||0}"></label><label>Custo (R$)<input name="cost" type="number" min="0" step="0.01" value="${Number(product.cost)||0}"></label><label>Quantidade em estoque<input name="stock" type="number" min="0" max="100000" step="1" value="${Number(product.stock)||0}"></label><label>Substituir foto (opcional)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="product-status-toggle"><input name="soldOut" type="checkbox" ${product.soldOut?'checked':''}> Marcar como esgotado</label><label class="wide">Descrição<textarea name="description" maxlength="500" rows="2">${esc(product.description||'')}</textarea></label><label class="wide">Link de vídeo (opcional)<input name="videoUrl" type="url" maxlength="500" value="${esc(product.videoUrl||'')}" placeholder="https://youtube.com/…"></label></div><p class="product-values">Venda: <strong>${currency(product.price)}</strong><span>·</span> Custo: <strong>${currency(product.cost)}</strong>${product.videoUrl?`<span>·</span><a href="${esc(product.videoUrl)}" target="_blank" rel="noreferrer">Ver vídeo ↗</a>`:''}</p><div class="request-actions"><span class="request-save-message" role="status"></span><button class="button button-primary save-product" type="button">Salvar alterações</button><button class="small-button delete-product" type="button">Excluir cadastro</button></div></article>`;}
function renderProducts(){const list=$('#product-list');$('#product-count').textContent=`${products.length} ${products.length===1?'produto':'produtos'}`;list.innerHTML=products.length?products.map(productCard).join(''):'<div class="empty-note">Nenhum produto cadastrado ainda.</div>';}
async function loadProducts(){const response=await fetch('/api/admin/products');if(!response.ok)throw new Error('Não foi possível carregar os produtos.');products=(await response.json()).products;renderProducts();}
async function mediaPayload(file,videoUrl){let imageData='',imageType='';if(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>4_000_000)throw new Error('A foto deve ser JPG, PNG ou WebP de até 4 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));imageData=btoa(binary);imageType=file.type;}return {imageData,imageType,videoUrl};}
async function saveProductMedia(id,file,videoUrl){const payload=await mediaPayload(file,videoUrl||'');const response=await fetch(`/api/admin/products/${encodeURIComponent(id)}/media`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Produto salvo, mas não foi possível salvar a foto ou o vídeo.');}
let purchases=[];
function ownerPurchaseCard(purchase){return `<article class="purchase-admin-card" data-purchase-id="${esc(purchase.id)}"><div class="purchase-admin-heading"><div><span>${esc(purchase.category)} · ${new Date(purchase.createdAt).toLocaleString('pt-BR')}</span><h4>${esc(purchase.productName)} × ${purchase.quantity}</h4></div><strong>${currency(purchase.total)}</strong></div><p>Cliente: ${esc(purchase.customerName)} · ${esc(purchase.customerEmail)}</p><div class="purchase-admin-controls"><label>Pagamento<select name="paymentStatus"><option ${purchase.paymentStatus==='Pendente'?'selected':''}>Pendente</option><option ${purchase.paymentStatus==='Pago'?'selected':''}>Pago</option></select></label><label>Andamento<select name="status">${['Recebida','Em separação','Pronta para retirada','Entregue','Cancelada'].map(status=>`<option ${purchase.status===status?'selected':''}>${status}</option>`).join('')}</select></label><span>Forma escolhida: <b>${esc(purchase.paymentMethod)}</b></span></div><div class="request-actions"><span class="request-save-message" role="status"></span>${purchase.status==='Entregue'?'<button type="button" class="small-button print-purchase-receipt">Comprovante PDF</button>':''}<button type="button" class="button button-primary save-purchase-status">Atualizar compra</button></div></article>`;}
async function loadPurchases(){const response=await fetch('/api/admin/purchases');if(!response.ok)throw new Error('Não foi possível carregar as compras.');purchases=(await response.json()).purchases;$('#purchase-count').textContent=`${purchases.length} ${purchases.length===1?'compra':'compras'}`;$('#purchase-list').innerHTML=purchases.length?purchases.map(ownerPurchaseCard).join(''):'<div class="empty-note">Nenhuma compra de cliente recebida.</div>';}
function renderMonthlyReport(report,closed){monthlyReport=report;$('#report-state').textContent=closed?'Fechado':'Em andamento';$('#report-state').classList.toggle('closed',closed);$('#download-report').disabled=!closed;$('#report-revenue').textContent=currency(report.revenue);$('#report-expenses').textContent=currency(report.expenses);$('#report-expenses-percent').textContent=`${percent(report.expensePercent)} da receita lançada`;$('#report-profit').textContent=currency(report.profit);$('#report-profit-percent').textContent=`${percent(report.profitPercent)} de margem nos lançamentos completos`;$('#report-tithe').textContent=currency(report.tithe);$('#report-tithe-percent').textContent='10% do lucro positivo';$('#report-received').textContent=currency(report.received);$('#report-pending').textContent=`A receber: ${currency(report.pending)}`;$('#report-order-count').textContent=`${report.ordersCount} lançamentos no mês · ${report.completeOrders} com dados completos`;$('#report-incomplete-note').textContent=report.incompleteCount?`${report.incompleteCount} lançamento(s) sem valor cobrado ou custo informado não entram no cálculo de lucro e dízimo.`:'Lançamentos sem valor cobrado ou custo informado não entram no cálculo de lucro e dízimo.';const sourceData=report.sources||{repairs:{revenue:report.revenue,expenses:report.expenses,profit:report.profit,received:report.received,pending:report.pending,count:report.ordersCount,profitPercent:report.profitPercent},sales:{revenue:0,expenses:0,profit:0,received:0,pending:0,count:0,profitPercent:0}};$('#report-sources').innerHTML=[['Reparos · Caixa',sourceData.repairs],['Vendas · produtos',sourceData.sales]].map(([title,source])=>`<article class="report-source-card"><div><h3>${esc(title)}</h3><span>${Number(source.count)||0} lançamento(s) · ${percent(source.profitPercent)} de margem · ${percent(report.revenue>0?Number(source.revenue)/report.revenue*100:0)} da receita total</span></div><dl><div><dt>Receita</dt><dd>${currency(source.revenue)}</dd></div><div><dt>Despesas</dt><dd>${currency(source.expenses)}</dd></div><div><dt>Lucro</dt><dd>${currency(source.profit)}</dd></div><div><dt>Recebido</dt><dd>${currency(source.received)}</dd></div><div><dt>A receber</dt><dd>${currency(source.pending)}</dd></div></dl></article>`).join('');const bars=[{label:'Receita',value:report.revenue,pct:100},{label:'Despesas',value:report.expenses,pct:report.expensePercent},{label:'Lucro',value:report.profit,pct:report.profitPercent},{label:'Dízimo',value:report.tithe,pct:10}];const scale=Math.max(...bars.map(item=>Math.abs(Number(item.value)||0)),1);$('#report-chart').innerHTML=bars.map(item=>`<div class="report-bar-row"><div class="report-bar-label"><span>${esc(item.label)}</span><strong>${currency(item.value)}</strong></div><div class="report-bar-track" role="img" aria-label="${esc(item.label)}: ${currency(item.value)}, ${percent(item.pct)}"><span style="width:${Math.min(100,Math.abs(Number(item.value)||0)/scale*100)}%" class="${item.label==='Despesas'?'expense':''}"></span></div><small>${percent(item.pct)} ${item.label==='Despesas'?'da receita':item.label==='Lucro'?'de margem':'do lucro positivo'}</small></div>`).join('');}
async function loadMonthlyReport(){const month=$('#report-month').value;const status=$('#report-message');if(!month){status.textContent='Escolha um mês para consultar.';return;}status.textContent='Carregando relatório…';$('#download-report').disabled=true;try{const response=await fetch(`/api/admin/reports?month=${encodeURIComponent(month)}`);const data=await response.json();if(!response.ok)throw new Error(data.error||'Não foi possível carregar o relatório.');renderMonthlyReport(data.report,data.closed);showTitheReceipt(data.report.titheReceipt,month);status.textContent=data.closed?'Relatório fechado com o comprovante do dízimo. O PDF está pronto para baixar e assinar.':'Relatório atualizado com os lançamentos do Caixa. Anexe a foto do comprovante do dízimo para fechar o mês e liberar o PDF.';}catch(error){status.textContent=error.message;}}
async function showTitheReceipt(receipt,month){const image=$('#tithe-receipt-preview');$('#delete-tithe-receipt').hidden=!receipt;if(titheReceiptUrl){URL.revokeObjectURL(titheReceiptUrl);titheReceiptUrl=null;}if(!receipt){image.hidden=true;image.removeAttribute('src');return;}try{const response=await fetch(`/api/admin/reports/tithe-receipt?month=${encodeURIComponent(month)}`);if(!response.ok)throw new Error('Não foi possível exibir a foto anexada.');const blob=await response.blob();if($('#report-month').value!==month)return;titheReceiptUrl=URL.createObjectURL(blob);image.src=titheReceiptUrl;image.hidden=false;}catch(error){$('#tithe-receipt-message').textContent=error.message;}}
async function saveTitheReceipt(){const status=$('#tithe-receipt-message');const file=$('#tithe-receipt-file').files[0];const month=$('#report-month').value;if(!file){status.textContent='Escolha uma foto do comprovante.';return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>4_000_000){status.textContent='Escolha uma foto JPG, PNG ou WebP de até 4 MB.';return;}status.textContent='Enviando foto…';const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));try{const response=await fetch(`/api/admin/reports/tithe-receipt?month=${encodeURIComponent(month)}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({month,type:file.type,data:btoa(binary)})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível anexar a foto.');$('#tithe-receipt-file').value='';status.textContent='Comprovante anexado ao relatório.';await loadMonthlyReport();$('#tithe-receipt-message').textContent='Comprovante anexado ao relatório.';}catch(error){status.textContent=error.message;}}
$('#save-tithe-receipt').addEventListener('click',saveTitheReceipt);
$('#delete-tithe-receipt').addEventListener('click',async()=>{if(!confirm('Apagar a foto do comprovante deste mês?'))return;const status=$('#tithe-receipt-message');status.textContent='Apagando foto…';try{const response=await fetch(`/api/admin/reports/tithe-receipt?month=${encodeURIComponent($('#report-month').value)}`,{method:'DELETE'});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível apagar a foto.');await loadMonthlyReport();$('#tithe-receipt-message').textContent='Foto do comprovante apagada.';}catch(error){status.textContent=error.message;}});
function switchTab(name){document.querySelectorAll('.dashboard-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.tab===name));document.querySelectorAll('.dashboard-panel').forEach(panel=>panel.classList.toggle('active',panel.id===`panel-${name}`));}
document.querySelectorAll('.dashboard-tab').forEach(tab=>tab.addEventListener('click',()=>switchTab(tab.dataset.tab)));
document.querySelector('[data-tab="reports"]').addEventListener('click',()=>loadMonthlyReport());
$('#report-month').value=new Date().toLocaleDateString('sv-SE',{timeZone:'America/Sao_Paulo'}).slice(0,7);
$('#load-report').addEventListener('click',loadMonthlyReport);
$('#report-month').addEventListener('change',loadMonthlyReport);
$('#download-report').addEventListener('click',()=>{if(monthlyReport?.closedAt)location.href=`/api/admin/reports.pdf?month=${encodeURIComponent($('#report-month').value)}`;});
document.querySelectorAll('[data-go-tab]').forEach(button=>button.addEventListener('click',()=>switchTab(button.dataset.goTab)));
document.querySelectorAll('[data-add]').forEach(button=>button.addEventListener('click',()=>{const path=button.dataset.add;const box=document.querySelector(`[data-repeat="${path}"]`);let entries;if(path==='socialLinks')entries=[...box.querySelectorAll('.editor-row')].map(row=>({name:row.querySelector('[data-item="name"]').value,url:row.querySelector('[data-item="url"]').value}));else if(path==='reviews')entries=[...box.querySelectorAll('.editor-row')].map(row=>({name:row.querySelector('[data-item="name"]').value,rating:row.querySelector('[data-item="rating"]').value,text:row.querySelector('[data-item="text"]').value}));else entries=[...box.querySelectorAll('.editor-row')].map(row=>({title:row.querySelector('[data-item="title"]').value,description:row.querySelector('[data-item="description"]').value}));entries.push(path==='socialLinks'?{name:'',url:''}:path==='reviews'?{name:'',rating:5,text:''}:{title:'',description:''});renderRepeater(path,entries);}));
document.addEventListener('click',event=>{if(event.target.matches('.remove-row')){const box=event.target.closest('[data-repeat]');if(event.target.matches('.remove-photo')){event.target.closest('.photo-item').remove();return;}const row=event.target.closest('.editor-row');row.remove();box.querySelectorAll('.editor-row').forEach((item,index)=>{item.querySelector('label').firstChild.textContent=`${box.dataset.label} ${index+1}`;});}});
$('#upload-photo').addEventListener('click',async()=>{const file=$('#gallery-file').files[0];const status=$('#photo-message');if(!file){status.textContent='Escolha uma imagem primeiro.';return;}status.textContent='Enviando foto…';try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let index=0;index<bytes.length;index+=32768)binary+=String.fromCharCode(...bytes.subarray(index,index+32768));const response=await fetch('/api/admin/photos',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type:file.type,data:btoa(binary),caption:$('#gallery-caption').value,videoUrl:$('#gallery-video-url').value})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível enviar a foto.');settings.gallery=[...(settings.gallery||[]),result.photo].slice(0,24);renderGallery(settings.gallery);$('#gallery-file').value='';$('#gallery-caption').value='';$('#gallery-video-url').value='';status.textContent='Foto publicada. Os clientes já podem comentar; você pode apagar a publicação ou qualquer comentário pelo painel.';}catch(error){status.textContent=error.message;}});
$('#settings-form').addEventListener('submit',async event=>{event.preventDefault();const status=$('#settings-message');status.textContent='Salvando…';try{const response=await fetch('/api/admin/settings',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(gatherSettings())});const data=await response.json();if(!response.ok)throw new Error(data.error||'Não foi possível salvar.');loadEditor(data.settings);status.textContent='Alterações salvas. O site público já foi atualizado.';}catch(error){status.textContent=error.message;}});
$('#requests').addEventListener('click',async event=>{const button=event.target.closest('.save-request,.publish-progress,.delete-request');if(!button)return;const card=button.closest('[data-request]');if(button.matches('.delete-request')){if(!confirm('Apagar esta solicitação de serviço e suas atualizações? Esta ação não pode ser desfeita.'))return;button.disabled=true;try{const response=await fetch(`/api/admin/requests/${encodeURIComponent(card.dataset.request)}`,{method:'DELETE'});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível apagar a solicitação.');await loadRequests();}catch(error){card.querySelector('.request-save-message').textContent=error.message;button.disabled=false;}return;}if(button.matches('.publish-progress')){const status=card.querySelector('.progress-feedback');const form=button.closest('.service-progress-form');const file=form.querySelector('[name=progressPhoto]').files[0];if(file&&file.size>4*1024*1024){status.textContent='A foto deve ter até 4 MB.';return;}status.textContent='Publicando…';button.disabled=true;try{let imageData='';if(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));imageData=btoa(binary);}const response=await fetch(`/api/admin/requests/${encodeURIComponent(card.dataset.request)}/progress`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({imageType:file?.type||'',imageData,caption:form.querySelector('[name=progressCaption]').value.trim(),videoUrl:form.querySelector('[name=progressVideo]').value.trim()})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível publicar.');await loadRequests();}catch(error){status.textContent=error.message;button.disabled=false;}return;}const status=card.querySelector('.request-save-message');const payload={};card.querySelectorAll('.request-edit-grid [name]').forEach(input=>payload[input.name]=input.value.trim());status.textContent='Salvando…';button.disabled=true;try{const response=await fetch(`/api/admin/requests/${encodeURIComponent(card.dataset.request)}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível salvar.');status.textContent='Pedido atualizado.';await loadRequests();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
$('#review-list').addEventListener('click',async event=>{const button=event.target.closest('.save-review,.delete-review');if(!button)return;const card=button.closest('[data-review]');const status=card.querySelector('.request-save-message');const deleting=button.matches('.delete-review');if(deleting&&!confirm('Apagar esta avaliação? Ela também será removida do site.'))return;const payload={};if(!deleting){card.querySelectorAll('[name]').forEach(input=>payload[input.name]=input.value.trim());payload.rating=Number(payload.rating);}status.textContent=deleting?'Apagando…':'Salvando…';button.disabled=true;try{const response=await fetch(`/api/admin/reviews/${encodeURIComponent(card.dataset.review)}`,deleting?{method:'DELETE'}:{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível atualizar.');status.textContent=deleting?'Avaliação apagada.':'Avaliação atualizada.';await loadReviews();}catch(error){status.textContent=error.message;button.disabled=false;}});
$('#photo-comment-list').addEventListener('click',async event=>{const button=event.target.closest('.save-photo-comment,.delete-photo-comment');if(!button)return;const card=button.closest('[data-photo-comment-id]');const status=card.querySelector('.request-save-message');if(button.matches('.delete-photo-comment')&&!confirm('Apagar este comentário? Esta ação não pode ser desfeita.'))return;status.textContent=button.matches('.delete-photo-comment')?'Apagando…':'Salvando…';button.disabled=true;try{const response=await fetch(`/api/admin/photo-comments/${encodeURIComponent(card.dataset.photoCommentId)}`,button.matches('.delete-photo-comment')?{method:'DELETE'}:{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries([...card.querySelectorAll('[name]')].map(input=>[input.name,input.value.trim()]))) });const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível atualizar o comentário.');await loadPhotoComments();}catch(error){status.textContent=error.message;button.disabled=false;}});
$('#refresh-requests').addEventListener('click',()=>loadRequests().catch(error=>$('#requests').innerHTML=`<div class="empty-note">${esc(error.message)}</div>`));
$('#refresh-reviews').addEventListener('click',()=>loadReviews().catch(error=>$('#review-list').innerHTML=`<div class="empty-note">${esc(error.message)}</div>`));
$('#refresh-photo-comments').addEventListener('click',()=>loadPhotoComments().catch(error=>$('#photo-comment-list').innerHTML=`<div class="empty-note">${esc(error.message)}</div>`));
$('#cash-order-form').addEventListener('input',updateCashFormPreview);$('#cash-order-form').addEventListener('change',event=>{if(event.target.name!=='entryType')return;const field=$('#sale-item-type-field');field.hidden=event.target.value!=='Venda';if(field.hidden)$('#cash-order-form').elements.saleItemType.value='';});
$('#cash-order-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const status=$('#cash-form-feedback');const values=new FormData(form);const optionalMoney=field=>values.get(field)===""?null:Number(values.get(field));const payload={entryType:values.get('entryType'),saleItemType:values.get('saleItemType'),model:values.get('model').trim(),amountCharged:optionalMoney('amountCharged'),partCost:optionalMoney('partCost'),paymentStatus:values.get('paymentStatus'),paymentMethod:values.get('paymentMethod'),repairTime:values.get('repairTime').trim(),customerName:values.get('customerName').trim(),completionStatus:values.get('completionStatus')};status.textContent='Salvando lançamento…';try{const response=await fetch('/api/admin/cash-orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível salvar o lançamento.');form.reset();updateCashFormPreview();status.textContent='Lançamento salvo no caixa.';await loadCashOrders();}catch(error){status.textContent=error.message;}});
$('#cash-orders').addEventListener('input',event=>{const card=event.target.closest('[data-cash-order]');if(card)updateCashCardPreview(card);});$('#cash-orders').addEventListener('change',event=>{const card=event.target.closest('[data-cash-order]');if(!card||event.target.name!=='entryType')return;const field=card.querySelector('[data-sale-item-type]');field.hidden=event.target.value!=='Venda';if(field.hidden)field.querySelector('select').value='';});
$('#cash-orders').addEventListener('click',async event=>{const button=event.target.closest('.save-cash-order,.delete-cash-order');if(!button)return;const card=button.closest('[data-cash-order]');const message=card.querySelector('.request-save-message');const remove=button.matches('.delete-cash-order');if(remove&&!confirm('Apagar esta ordem do caixa? Esta ação não pode ser desfeita.'))return;button.disabled=true;message.textContent=remove?'Apagando ordem…':'Salvando ordem…';try{let options;if(remove)options={method:'DELETE'};else{const payload={};card.querySelectorAll('[name]').forEach(input=>payload[input.name]=input.value.trim());for(const field of ['amountCharged','partCost'])payload[field]=payload[field]===""?null:Number(payload[field]);options={method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)};}const response=await fetch(`/api/admin/cash-orders/${encodeURIComponent(card.dataset.cashOrder)}`,options);const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível atualizar a ordem.');await loadCashOrders();}catch(error){message.textContent=error.message;button.disabled=false;}});
$('#refresh-cash').addEventListener('click',()=>loadCashOrders().catch(error=>$('#cash-orders').innerHTML=`<div class="empty-note">${esc(error.message)}</div>`));
$('#product-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const feedback=$('#product-form-feedback');const button=form.querySelector('button[type="submit"]');const values=new FormData(form);const photo=values.get('photo');const payload={name:values.get('name').trim(),category:values.get('category'),price:Number(values.get('price')),cost:Number(values.get('cost')),stock:Number(values.get('stock')),soldOut:values.has('soldOut'),description:values.get('description').trim()};button.disabled=true;feedback.textContent='Salvando produto…';try{const response=await fetch('/api/admin/products',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível cadastrar o produto.');if((photo&&photo.size)||values.get('videoUrl'))await saveProductMedia(result.product.id,photo&&photo.size?photo:null,values.get('videoUrl'));form.reset();form.elements.price.value='0';form.elements.cost.value='0';form.elements.stock.value='0';feedback.textContent='Produto cadastrado.';await loadProducts();}catch(error){feedback.textContent=error.message;await loadProducts().catch(()=>{});}finally{button.disabled=false;}});
$('#product-list').addEventListener('click',async event=>{const button=event.target.closest('.save-product,.delete-product');if(!button)return;const card=button.closest('[data-product]');const feedback=card.querySelector('.request-save-message');const remove=button.matches('.delete-product');if(remove&&!confirm('Excluir este produto do catálogo?'))return;button.disabled=true;feedback.textContent=remove?'Excluindo produto…':'Salvando alterações…';try{let options;if(remove)options={method:'DELETE'};else{const values=[...card.querySelectorAll('[name]')];const payload=Object.fromEntries(values.filter(input=>!['photo','videoUrl'].includes(input.name)).map(input=>[input.name,input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value.trim()]));options={method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)};}const response=await fetch(`/api/admin/products/${encodeURIComponent(card.dataset.product)}`,options);const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível atualizar o produto.');if(!remove){const photo=card.querySelector('[name="photo"]').files[0];const videoUrl=card.querySelector('[name="videoUrl"]').value.trim();await saveProductMedia(card.dataset.product,photo,videoUrl);}await loadProducts();}catch(error){feedback.textContent=error.message;button.disabled=false;}});
$('#refresh-products').addEventListener('click',()=>loadProducts().catch(error=>$('#product-list').innerHTML=`<div class="empty-note">${esc(error.message)}</div>`));
$('#purchase-list').addEventListener('click',async event=>{const button=event.target.closest('.save-purchase-status');if(!button)return;const card=button.closest('.purchase-admin-card');const purchase=purchases.find(item=>item.id===card.dataset.purchaseId);if(!purchase)return;const message=card.querySelector('.request-save-message');button.disabled=true;message.textContent='Atualizando compra…';try{const response=await fetch(`/api/admin/purchases/${encodeURIComponent(purchase.id)}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({paymentStatus:card.querySelector('[name="paymentStatus"]').value,status:card.querySelector('[name="status"]').value})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível atualizar a compra.');await Promise.all([loadPurchases(),loadProducts()]);}catch(error){message.textContent=error.message;button.disabled=false;}});
$('#logout').addEventListener('click',async()=>{await fetch('/api/logout',{method:'POST'});location.href='/';});
async function initialize(){const settingsForm=$('#settings-form');settingsForm.querySelectorAll('button[type="submit"]').forEach(button=>button.disabled=true);const me=await fetch('/api/me').then(response=>response.json());if(!me.user||me.user.role!=='owner'){location.replace('/login.html?next=%2Fdashboard.html');return;}$('#owner-email').textContent=me.user.email;$('#overview-email').textContent=me.user.email;const settingsResponse=await fetch('/api/admin/settings');if(!settingsResponse.ok)throw new Error('Não foi possível carregar as configurações salvas.');loadEditor((await settingsResponse.json()).settings);settingsForm.querySelectorAll('button[type="submit"]').forEach(button=>button.disabled=false);const results=await Promise.allSettled([loadRequests(),loadReviews(),loadPhotoComments(),loadCashOrders(),loadMonthlyReport(),loadProducts(),loadPurchases()]);const targets=['#requests','#review-list','#photo-comment-list','#cash-orders','#report-message','#product-list','#purchase-list'];results.forEach((result,index)=>{if(result.status==='rejected')$(targets[index]).innerHTML=`<div class="empty-note">${esc(result.reason?.message||'Não foi possível carregar esta seção.')}</div>`;});}
initialize().catch(error=>{$('#settings-message').textContent=error.message;$('#settings-form').querySelectorAll('button[type="submit"]').forEach(button=>button.disabled=true);});

function addPurchaseReceiptButtons(){const list=$('#purchase-list');if(!list)return;for(const purchase of purchases.filter(item=>item.status==='Entregue')){const card=Array.from(list.querySelectorAll('.purchase-admin-card')).find(item=>item.dataset.purchaseId===purchase.id);const actions=card?.querySelector('.request-actions');if(!actions||actions.querySelector('.print-purchase-receipt'))continue;const button=document.createElement('button');button.type='button';button.className='small-button print-purchase-receipt';button.textContent='Comprovante PDF';actions.prepend(button);}}
const purchaseReceiptObserver=new MutationObserver(addPurchaseReceiptButtons);purchaseReceiptObserver.observe($('#purchase-list'),{childList:true});addPurchaseReceiptButtons();
$('#cash-orders').addEventListener('click',event=>{const button=event.target.closest('.print-cash-receipt');if(!button)return;const card=button.closest('[data-cash-order]');const order=cashOrders.find(item=>item.id===card?.dataset.cashOrder);if(!order)return;if(order.amountCharged===null||order.amountCharged===undefined){alert('Informe o valor cobrado e salve a ordem antes de gerar o comprovante.');return;}openReceiptPdf({kind:order.entryType==='Venda'?'venda':'reparo',reference:String(order.id).slice(-8).toUpperCase(),date:new Date(order.createdAt).toLocaleString('pt-BR'),customerName:order.customerName,customerPhone:order.customerPhone,item:order.model||'Aparelho não informado',amount:order.amountCharged,paymentStatus:order.paymentStatus,paymentMethod:order.paymentMethod,detail:order.repairTime?`Tempo de reparo: ${order.repairTime}`:''});});
$('#purchase-list').addEventListener('click',event=>{const button=event.target.closest('.print-purchase-receipt');if(!button)return;const card=button.closest('[data-purchase-id]');const purchase=purchases.find(item=>item.id===card?.dataset.purchaseId);if(!purchase||purchase.status!=='Entregue')return;openReceiptPdf({kind:'venda',reference:String(purchase.id).slice(-8).toUpperCase(),date:new Date(purchase.createdAt).toLocaleString('pt-BR'),customerName:purchase.customerName,customerEmail:purchase.customerEmail,item:`${purchase.productName} × ${purchase.quantity}`,amount:purchase.total,paymentStatus:purchase.paymentStatus,paymentMethod:purchase.paymentMethod,detail:`Categoria: ${purchase.category} · Situação: ${purchase.status}`});});
